using EqlTracker.Core;

public static class LiveAppearanceTests
{
    public static void Register(Action<string, Action> test)
    {
        void Check(bool value, string reason = "Assertion failed") { if (!value) throw new Exception(reason); }
        var time = new DateTime(2026, 10, 15, 12, 0, 0);
        Encounter Pair() => new() { Start = time, End = time.AddSeconds(10), PlayerDamage = 100,
            Events = [new() { Id = "log:10", Time = time, Actor = "ExampleHero", Owner = "Player", Target = "an orc", Kind = "Spell", Ability = "Spirit Tap IV", DamageType = "magic", Damage = 100 }],
            Heals = [new() { Id = "log:30", Time = time, Healer = "examplehero", HealerOwner = "Player", Recipient = "ExampleHero", Ability = "Spirit Tap", Effective = 60 }] };
        test("Linked healing uses actual restored HP and canonical ranks", () => { var f = Pair(); var row = DpsViews.Build([f], null, time, new() { Actor = "Player" }).Rows.Single(); Check(row.LinkedHealing == 60 && row.Damage == 100 && row.Dps == 10); });
        test("Linked healing follows enemy-target and damage critical filters", () => { var f = Pair(); Check(DamageHealing.Apply(CombatMetrics.Breakdown([f], new("Player", Target: "AN ORC")), [f], new("Player", Target: "AN ORC")).Single().LinkedHealing == 60); Check(DpsViews.Build([f], null, time, new() { Actor = "Player", CriticalOnly = true }).Rows.Count == 0); });
        test("Same-second ambiguous lifetaps never duplicate healing", () => { var f = Pair(); f.Events.Add(new() { Id = "log:20", Actor = "ExampleHero", Owner = "Player", Time = time, Ability = "Spirit Tap I", Kind = "Spell", Damage = 100 }); Check(DamageHealing.Link([f]).Count == 0); });
        test("Duplicate healing candidates remain unlinked", () => { var f = Pair(); var heal = f.Heals[0].Copy(); heal.Id = "log:31"; f.Heals.Add(heal); Check(DamageHealing.Link([f]).Count == 0); });
        test("Repeated same-second casts link only with verified alternating log order", () => { var f = Pair(); f.Events.Add(new() { Id = "log:40", Time = time, Actor = "ExampleHero", Owner = "Player", Ability = "Spirit Tap I", Kind = "Spell", Damage = 100 }); var heal = f.Heals[0].Copy(); heal.Id = "log:50"; f.Heals.Add(heal); Check(DamageHealing.Link([f]).Sum(h => h.Effective) == 120); heal.Id = "log:25"; Check(DamageHealing.Link([f]).Count == 0); });
        test("Unverified spell aliases remain recorded without damage badge", () => { var f = Pair(); f.Heals[0].Ability = "Unknown Recourse"; Check(DamageHealing.Link([f]).Count == 0 && f.Heals[0].Effective == 60); });
        test("Pet ownership mismatch cannot link another actor's heal", () => { var f = Pair(); f.Heals[0].HealerOwner = "Pet"; Check(DamageHealing.Link([f]).Count == 0); });
        test("Verified zero-effective lifetap displays zero rather than unknown", () => { var f = Pair(); f.Heals[0].Effective = 0; Check(DamageHealing.Link([f]).Single().Effective == 0); });
        test("Log ordering rejects a preceding unrelated heal", () => { var f = Pair(); f.Heals[0].Id = "log:5"; Check(DamageHealing.Link([f]).Count == 0); });
        test("Summary-only records invent neither linked heals nor peaks", () => { var f = Pair(); f.DetailAvailable = false; Check(DamageHealing.Link([f]).Count == 0); f.Events.Clear(); Check(CombatChart.Build([f], new()).Peaks.Count == 0); });
        test("Chart peaks are per-actor sampled DPS and earliest ties", () => { var f = Pair(); f.Events.Add(new() { Id = "log:40", Actor = "ExampleHero", Owner = "Player", Kind = "Melee", Damage = 100, Time = time.AddSeconds(2) }); var chart = CombatChart.Build([f], new()); Check(chart.Peaks.Single().Time == time && chart.Peaks.Single().Dps == 100 && chart.BinSeconds == 1); });
        test("Chart enemy filter retains its encounter time axis", () => { var f = Pair(); var chart = CombatChart.Build([f], new(Target: "other")); Check(chart.Duration == 10 && chart.Peaks.Count == 0); });
        test("Export acknowledgement and logging grammar parse", () => { var parser = new LogParser("ExampleHero"); string stamp = "[Thu Oct 15 12:00:00 2026] "; Check(parser.Parse(stamp + "Outputfile Complete: ExampleHero_example-Inventory.txt")!.InventoryExport == "ExampleHero_example-Inventory.txt"); Check(parser.Parse(stamp + "Logging to 'eqlog.txt' is now *ON*.")!.LoggingEnabled); });
        test("Same-second inventory watermark keeps post-export loot once", () => { var snap = new InventorySnapshot { CapturedAt = time.AddMilliseconds(500), ExportLogId = "log:20", Entries = [new() { Name = "Diamond", Count = 1 }] }; InventoryParser.Apply(snap, new(time, "Diamond", "Looted", 1, ""), "log:10"); InventoryParser.Apply(snap, new(time, "Diamond", "Looted", 1, ""), "log:30"); Check(snap.Entries.Sum(e => e.Count) == 2 && snap.CapturedAt == time.AddMilliseconds(500) && snap.LastObservedChangeAt == time); });
        test("Other log generations use timestamps rather than unrelated offsets", () => { var snap = new InventorySnapshot { CapturedAt = time, ExportLogId = "old:100" }; InventoryParser.Apply(snap, new(time.AddSeconds(1), "Diamond", "Looted", 1, ""), "new:20"); Check(snap.Entries.Single().Count == 1 && snap.UpdatedAt == time.AddSeconds(1)); });
        test("Auto-sale does not decrement existing inventory or freshen its date", () => { var snap = new InventorySnapshot { CapturedAt = time, Entries = [new() { Name = "Diamond", Count = 3 }] }; InventoryParser.Apply(snap, new(time.AddSeconds(1), "Diamond", "Sold", 1, "")); Check(snap.Entries.Single().Count == 3 && snap.UpdatedAt == time); });
        test("Queue retains order while completed goals stop appearing", () => { var profile = new CharacterProfile { GoalQueue = [new() { QuestId = "wish1", ItemKey = "a", Name = "A" }, new() { QuestId = "wish2", ItemKey = "b", Name = "B" }] }; var rows = new List<ObjectiveRow> { new() { QuestId = "wish2", Key = "b", Needed = 2 }, new() { QuestId = "wish1", Key = "a", Needed = 1, Owned = 1 } }; Check(ObjectiveQueue.Fallback(profile, new(), rows).Single().Key == "b" && profile.GoalQueue.Count == 2); });
        test("Disabled class queue goals pause instead of completing", () => { var profile = new CharacterProfile { CurrentClasses = [], OptionalClasses = [], GoalQueue = [new() { QuestId = "war", ItemKey = "a" }] }; var catalog = new Catalog { Quests = [new() { Id = "war", Class = "WAR" }] }; Check(ObjectiveQueue.Build(profile, catalog, []).Single().Status == "Paused"); });
        test("Queue unknown catalog reference stays unresolved", () => { var profile = new CharacterProfile { GoalQueue = [new() { QuestId = "gone", ItemKey = "missing" }] }; Check(ObjectiveQueue.Build(profile, new(), []).Single().Status == "Unresolved"); });
        test("Current-zone-only never silently suggests or queues goals", () => { var p = new CharacterProfile { ObjectiveMode = "Current zone only" }; Check(ObjectiveQueue.Fallback(p, new(), [new() { Needed = 1 }]).Count == 0); });
        test("Automatic sync remains off until opted in and verified", () => { var s = new NativeSyncSettings { Key = 120 }; Check(!NativeSyncPolicy.Due(s, time, true)); s.Login = true; Check(!NativeSyncPolicy.Due(s, time, true)); s.Verified = true; Check(NativeSyncPolicy.Due(s, time, true) && !NativeSyncPolicy.Due(s, time, false)); });
        test("Periodic sync respects successful cadence and coalesces missed intervals", () => { var s = new NativeSyncSettings { Key = 120, Verified = true, Periodic = true, LastSuccess = time, IntervalHours = 2 }; Check(!NativeSyncPolicy.Due(s, time.AddMinutes(119), false)); Check(NativeSyncPolicy.Due(s, time.AddHours(8), false)); s.LastSuccess = time.AddHours(8); Check(!NativeSyncPolicy.Due(s, time.AddHours(8), false)); });
        test("Automatic sync cannot steal focus or interrupt input and fear pauses", () => { Check(NativeSyncPolicy.Eligible(true, 5, false, false, false)); Check(!NativeSyncPolicy.Eligible(false, 6, false, false, false)); Check(!NativeSyncPolicy.Eligible(true, 4, false, false, false)); Check(!NativeSyncPolicy.Eligible(true, 6, true, false, false)); Check(!NativeSyncPolicy.Eligible(true, 6, false, true, false)); Check(!NativeSyncPolicy.Eligible(true, 6, false, false, true)); });
        test("Sync cannot succeed on acknowledgement without a complete import", () => { var r = new SyncRequest { RequestedAt = time, Logging = true, Who = true, Export = true }; Check(r.Outcome(time.AddSeconds(3)) == "Awaiting evidence"); Check(r.Outcome(time.AddSeconds(15)) == "Partial"); r.Imported = true; Check(r.Outcome(time.AddSeconds(15)) == "Complete"); });
        test("Failed sync reaches terminal state without blind retries", () => { var r = new SyncRequest { RequestedAt = time }; Check(r.Outcome(time.AddSeconds(15)) == "Failed"); r.State = "Failed"; Check(!r.Active); });
        test("Additive settings preserve older profiles with safe defaults", () => { var p = System.Text.Json.JsonSerializer.Deserialize<CharacterProfile>("{\"Character\":\"ExampleHero\"}")!; Check(p.ShowLinkedHealing && p.ObjectiveMode == "My queue" && !p.NativeSync.Login && !p.NativeSync.Periodic && !p.NativeSync.Verified && p.NativeSync.IntervalHours == 2); });
        test("Inventory and queue observation state survive restart serialization", () => { var p = new CharacterProfile { GoalQueue = [new() { QuestId = "q", ItemKey = "k", Name = "Pin" }] }; var saved = System.Text.Json.JsonSerializer.Deserialize<CharacterProfile>(System.Text.Json.JsonSerializer.Serialize(p))!; Check(saved.GoalQueue.Single().Id == "q|k"); var snap = new InventorySnapshot { CapturedAt = time, LastObservedChangeAt = time.AddMinutes(1), ExportLogId = "log:55" }; var restored = System.Text.Json.JsonSerializer.Deserialize<InventorySnapshot>(System.Text.Json.JsonSerializer.Serialize(snap))!; Check(restored.UpdatedAt == snap.UpdatedAt && restored.ExportLogId == "log:55"); });
    }
}
